        let rejectPublic;

        const operation = {

            generation,

            settled: false,

            promise: null,

            lifecycleAuthorities,

        };

        operation.promise = new VGPU_NATIVE_PROMISE((resolve, reject) => {

            resolvePublic = resolve;

            rejectPublic = reject;

        });

