            buffer: call('buffer'),

            bindings: call('bindings'),

            shader: call('shader'),

            pipeline: call('pipeline'),

            texture: call('texture'),

            ring: call('ring'),

            bundles: call('bundles'),

            scheduler: call('scheduler'),

            warmup: call('warmup'),

            leaks: leakTracking ? call('getLeaks').length : 'disabled',

            memory: call('memory'),

